import{_ as l,a0 as d,w as o,s as r,ao as p,I as n,a1 as i,A as t,x as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const m=JSON.parse('{"title":"如何在 CentOS、RHEL 和 Fedora 上安装 DHCP 服务 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 CentOS、RHEL 和 Fedora 上安装 DHCP 服务 | LCTT (201704) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 CentOS、RHEL 和 Fedora 上安装 DHCP 服务 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 CentOS、RHEL 和 Fedora 上安装 DHCP 服务 | LCTT (201704) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201704/20170321 How to Install a DHCP Server in CentOS RHEL and Fedora","title":"如何在 CentOS、RHEL 和 Fedora 上安装 DHCP 服务","tag":"201704","desc":""},"relativePath":"201704/20170321 How to Install a DHCP Server in CentOS RHEL and Fedora.md","filePath":"[post].md"}'),h={name:"201704/20170321 How to Install a DHCP Server in CentOS RHEL and Fedora.md"};function c(g,s,C,u,k,b){const e=d("Link");return o(),r("div",null,[s[16]||(s[16]=p(`<h1 id="如何在-centos、rhel-和-fedora-上安装-dhcp-服务" tabindex="-1">如何在 CentOS、RHEL 和 Fedora 上安装 DHCP 服务 <a class="header-anchor" href="#如何在-centos、rhel-和-fedora-上安装-dhcp-服务" aria-label="Permalink to “如何在 CentOS、RHEL 和 Fedora 上安装 DHCP 服务”">​</a></h1><p>DHCP（Dynamic Host Configuration Protocol）是一个网络协议，它使得服务器能从预定义的 IP 池中为网络中的客户端节点自动分配 IP 地址并提供其它相关的网络配置参数。</p><p>这意味着每次客户端节点启动（连接到网络）的时候，它都会获得一个和从不改变的“静态” IP 地址相反的“动态” IP 地址。DHCP 服务器给 DHCP 客户端分配 IP 地址称为“租约”，租约时间随客户端需要的连接时间或 DHCP 的配置而异。</p><p>在这篇指南中，我们会介绍如何在 CentOS/RHEL 和 Fedora 发行版中安装和配置 DHCP 服务。</p><h3 id="设置测试环境" tabindex="-1">设置测试环境 <a class="header-anchor" href="#设置测试环境" aria-label="Permalink to “设置测试环境”">​</a></h3><p>本次安装中我们使用如下的测试环境：</p><ul><li>DHCP 服务器 - CentOS 7</li><li>DHCP 客户端 - Fedora 25 和 Ubuntu 16.04</li></ul><h3 id="dhcp-如何工作" tabindex="-1">DHCP 如何工作？ <a class="header-anchor" href="#dhcp-如何工作" aria-label="Permalink to “DHCP 如何工作？”">​</a></h3><p>在进入下一步之前，让我们首先了解一下 DHCP 的工作流程：</p><ul><li>当已连接到网络的客户端计算机（配置为使用 DHCP）启动时，它会发送一个 <code>DHCPDISCOVER</code> 消息到 DHCP 服务器。</li><li>当 DHCP 服务器接收到 <code>DHCPDISCOVER</code> 请求消息时，它会回复一个 <code>DHCPOFFER</code> 消息。</li><li>客户端收到 <code>DHCPOFFER</code> 消息后，它再发送给服务器一个 <code>DHCPREQUEST</code> 消息，表示客户端已准备好获取 <code>DHCPOFFER</code> 消息中提供的网络配置。</li><li>最后，DHCP 服务器收到客户端的 <code>DHCPREQUEST</code> 消息，并回复 <code>DHCPACK</code> 消息，表示允许客户端使用分配给它的 IP 地址。</li></ul><h3 id="第一步-在-centos-上安装-dhcp-服务" tabindex="-1">第一步：在 CentOS 上安装 DHCP 服务 <a class="header-anchor" href="#第一步-在-centos-上安装-dhcp-服务" aria-label="Permalink to “第一步：在 CentOS 上安装 DHCP 服务”">​</a></h3><p>1、安装 DHCP 服务非常简单，只需要运行下面的命令即可。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ yum -y install dhcp</span></span></code></pre></div><p>重要：假如系统中有多个网卡，但你想只在其中一个网卡上启用 DHCP 服务，可以按照下面的步骤在该网卡上启用 DHCP 服务。</p><p>2、 打开文件 <code>/etc/sysconfig/dhcpd</code>，将指定网卡的名称添加到 <code>DHCPDARGS</code> 列表，假如网卡名称为 <code>eth0</code>，则添加：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>DHCPDARGS=eth0</span></span></code></pre></div><p>保存文件并退出 。</p><h3 id="第二步-在-centos-上配置-dhcp-服务" tabindex="-1">第二步：在 CentOS 上配置 DHCP 服务 <a class="header-anchor" href="#第二步-在-centos-上配置-dhcp-服务" aria-label="Permalink to “第二步：在 CentOS 上配置 DHCP 服务”">​</a></h3><p>3、 对于初学者来说，配置 DHCP 服务的第一步是创建 <code>dhcpd.conf</code> 配置文件，DHCP 主要配置文件一般是 <code>/etc/dhcp/dhcpd.conf</code>（默认情况下该文件为空），该文件保存了发送给客户端的所有网络信息。</p><p>但是，有一个样例配置文件 <code>/usr/share/doc/dhcp*/dhcpd.conf.sample</code>，这是配置 DHCP 服务的良好开始。</p><p>DHCP 配置文件中定义了两种类型的语句：</p><ul><li>参数 - 说明如何执行任务、是否执行任务、或者给 DHCP 客户端发送什么网络配置选项。</li><li>声明 - 指定网络拓扑、定义客户端、提供客户端地址、或将一组参数应用于一组声明。</li></ul><p>因此，首先复制示例配置文件为主配置文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cp /usr/share/doc/dhcp-4.2.5/dhcpd.conf.example /etc/dhcp/dhcpd.conf</span></span></code></pre></div><p>4、 然后，打开主配置文件并定义你的 DHCP 服务选项：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ vi /etc/dhcp/dhcpd.conf</span></span></code></pre></div><p>首先在文件开头设置以下应用于全部子网的全局参数（注意要使用你实际场景中的值）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>option domain-name &quot;tecmint.lan&quot;;</span></span>
<span class="line"><span>option domain-name-servers ns1.tecmint.lan, ns2.tecmint.lan;</span></span>
<span class="line"><span>default-lease-time 3600; </span></span>
<span class="line"><span>max-lease-time 7200;</span></span>
<span class="line"><span>authoritative;</span></span></code></pre></div><p>5、 然后，定义一个子网；在这个事例中，我们会为 <code>192.168.56.0/24</code> 局域网配置 DHCP（注意使用你实际场景中的值）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>subnet 192.168.56.0 netmask 255.255.255.0 {</span></span>
<span class="line"><span>option routers                  192.168.56.1;</span></span>
<span class="line"><span>option subnet-mask              255.255.255.0;</span></span>
<span class="line"><span>option domain-search            &quot;tecmint.lan&quot;;</span></span>
<span class="line"><span>option domain-name-servers      192.168.56.1;</span></span>
<span class="line"><span>range   192.168.56.10   192.168.56.100;</span></span>
<span class="line"><span>range   192.168.56.120  192.168.56.200;</span></span>
<span class="line"><span>}</span></span></code></pre></div><h3 id="第三步-为-dhcp-客户端分配静态-ip" tabindex="-1">第三步：为 DHCP 客户端分配静态 IP <a class="header-anchor" href="#第三步-为-dhcp-客户端分配静态-ip" aria-label="Permalink to “第三步：为 DHCP 客户端分配静态 IP”">​</a></h3><p>只需要在 <code>/etc/dhcp/dhcpd.conf</code> 文件中定义下面的部分，其中你必须显式指定它的 MAC 地址和打算分配的 IP，你就可以为网络中指定的客户端计算机分配一个静态 IP 地址：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>host ubuntu-node {</span></span>
<span class="line"><span>hardware  ethernet 00:f0:m4:6y:89:0g;</span></span>
<span class="line"><span>fixed-address 192.168.56.105;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>host fedora-node {</span></span>
<span class="line"><span>hardware  ethernet 00:4g:8h:13:8h:3a;</span></span>
<span class="line"><span>fixed-address 192.168.56.110;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>保存文件并关闭。</p><p>注意：你可以使用下面的命令找到 Linux 的 MAC 地址。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ifconfig -a eth0 | grep HWaddr</span></span></code></pre></div><p>6、 现在，使用下面的命令启动 DHCP 服务，并使在下次系统启动时自动启动：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>---------- On CentOS/RHEL 7 ---------- </span></span>
<span class="line"><span>$ systemctl start dhcpd</span></span>
<span class="line"><span>$ systemctl enable dhcpd</span></span>
<span class="line"><span>---------- On CentOS/RHEL 6 ----------</span></span>
<span class="line"><span>$ service dhcpd start</span></span>
<span class="line"><span>$ chkconfig dhcpd on</span></span></code></pre></div><p>7、 另外，别忘了使用下面的命令允许 DHCP 服务通过防火墙（DHCPD 守护进程通过 UDP 监听67号端口）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>---------- On CentOS/RHEL 7 ----------</span></span>
<span class="line"><span>$ firewall-cmd --add-service=dhcp --permanent </span></span>
<span class="line"><span>$ firewall-cmd --reload </span></span>
<span class="line"><span>---------- On CentOS/RHEL 6 ----------</span></span>
<span class="line"><span>$ iptables -A INPUT -p tcp -m state --state NEW --dport 67 -j ACCEPT</span></span>
<span class="line"><span>$ service iptables save</span></span></code></pre></div><h3 id="第四步-配置-dhcp-客户端" tabindex="-1">第四步：配置 DHCP 客户端 <a class="header-anchor" href="#第四步-配置-dhcp-客户端" aria-label="Permalink to “第四步：配置 DHCP 客户端”">​</a></h3><p>8、 现在，你可以为网络中的客户端配置自动从 DHCP 服务器中获取 IP 地址。登录到客户端机器并按照下面的方式修改以太网接口的配置文件（注意网卡的名称和编号）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># vi /etc/sysconfig/network-scripts/ifcfg-eth0</span></span></code></pre></div><p>添加下面的选项：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>DEVICE=eth0</span></span>
<span class="line"><span>BOOTPROTO=dhcp</span></span>
<span class="line"><span>TYPE=Ethernet</span></span>
<span class="line"><span>ONBOOT=yes</span></span></code></pre></div><p>保存文件并退出。</p><p>9、 你也可以在桌面服务器中按照下面的截图（Ubuntu 16.04桌面版）通过 GUI 设置 <code>Method</code> 为 <code>Automatic (DHCP)</code>。</p>`,47)),n("p",null,[i(e,{href:"http://www.tecmint.com/wp-content/uploads/2017/03/Set-DHCP-in-Client-Network.png"},{default:t(()=>[...s[0]||(s[0]=[n("img",{src:"http://www.tecmint.com/wp-content/uploads/2017/03/Set-DHCP-in-Client-Network.png",alt:"Set DHCP in Client Network"},null,-1)])]),_:1})]),s[17]||(s[17]=p(`<p><em>在客户端网络中设置 DHCP</em></p><p>10、 按照下面的命令重启网络服务（你也可以通过重启系统）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>---------- On CentOS/RHEL 7 ----------</span></span>
<span class="line"><span>$ systemctl restart network</span></span>
<span class="line"><span>---------- On CentOS/RHEL 6 ----------</span></span>
<span class="line"><span>$ service network restart</span></span></code></pre></div><p>到了这里，如果所有设置都是正确的，你的客户端就应该能自动从 DHCP 服务器中获取 IP 地址。</p><p>你也可以阅读：</p>`,5)),n("ol",null,[n("li",null,[i(e,{href:"http://www.tecmint.com/install-and-configure-multihomed-isc-dhcp-server-on-debian-linux/"},{default:t(()=>[...s[1]||(s[1]=[a("如何在 Debian Linux 中安装和配置 Multihomed ISC DHCP 服务",-1)])]),_:1})]),n("li",null,[i(e,{href:"http://www.tecmint.com/ip-command-examples/"},{default:t(()=>[...s[2]||(s[2]=[a("配置网络的10个有用的 “IP” 命令",-1)])]),_:1})])]),s[18]||(s[18]=n("p",null,"在这篇文章中我们为你展示了如何在 RHEL/CentOS 中安装 DHCP 服务。在下面的评论框中给我们反馈吧。在接下来的文章中，我们还会为你展示如何在 Debian/Ubuntu 中安装 DHCP 服务。和 TecMint 保持联系。",-1)),s[19]||(s[19]=n("hr",null,null,-1)),s[20]||(s[20]=n("p",null,"作者简介：",-1)),s[21]||(s[21]=n("p",null,"Aaron Kili 是一个 Linux 和 F.O.S.S 的爱好者，即将推出的 Linux SysAdmin 网络开发人员，目前也是 TecMint 的内容创作者，他喜欢和电脑一起工作，并且坚信共享知识。",-1)),s[22]||(s[22]=n("hr",null,null,-1)),n("p",null,[s[4]||(s[4]=a("via: ",-1)),i(e,{href:"http://www.tecmint.com/install-dhcp-server-in-centos-rhel-fedora/"},{default:t(()=>[...s[3]||(s[3]=[a("http://www.tecmint.com/install-dhcp-server-in-centos-rhel-fedora/",-1)])]),_:1})]),n("p",null,[s[8]||(s[8]=a("作者：",-1)),i(e,{href:"http://www.tecmint.com/author/aaronkili/"},{default:t(()=>[...s[5]||(s[5]=[a("Aaron Kili",-1)])]),_:1}),s[9]||(s[9]=a(" 译者：",-1)),i(e,{href:"https://github.com/ictlyh"},{default:t(()=>[...s[6]||(s[6]=[a("ictlyh",-1)])]),_:1}),s[10]||(s[10]=a(" 校对：",-1)),i(e,{href:"https://github.com/wxy"},{default:t(()=>[...s[7]||(s[7]=[a("wxy",-1)])]),_:1})]),n("p",null,[s[13]||(s[13]=a("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[11]||(s[11]=[a("LCTT",-1)])]),_:1}),s[14]||(s[14]=a(" 原创编译，",-1)),i(e,{href:"https://linux.cn/"},{default:t(()=>[...s[12]||(s[12]=[a("Linux中国",-1)])]),_:1}),s[15]||(s[15]=a(" 荣誉推出",-1))])])}const H=l(h,[["render",c]]);export{m as __pageData,H as default};
